    // 1. Validate pointers first to avoid dereferencing NULLs later
    if ((field == NULL) || (gain == NULL) || (field_direction == NULL) || (scheduled_axis_gain == NULL)) {
        return ADCS_E_NULL;
    }

    // 2. Initialize failure outputs to zero as required by spec
    *gain = 0.0;
    field_direction->x = 0.0;
    field_direction->y = 0.0;
    field_direction->z = 0.0;
    scheduled_axis_gain->x = 0.0;
    scheduled_axis_gain->y = 0.0;
    scheduled_axis_gain->z = 0.0;

    // 3. Validate scalar parameter ranges and finiteness
    if ((!isfinite(base_gain)) || (base_gain < 0.0) ||
        (!isfinite(reference_field)) || (reference_field <= 0.0) ||
        (!isfinite(min_gain)) || (min_gain < 0.0) ||
        (!isfinite(max_gain)) || (max_gain < min_gain)) {
        return ADCS_E_RANGE;
    }

    // 4. Validate input vector finiteness
    if (!adcs_is_finite_vec3(field)) {
        return ADCS_E_RANGE;
    }

    // 5. Compute magnetic field magnitude
    double b_norm = adcs_vec3_norm(field);

    // 6. Check for degenerate case (zero-length vector)
    if (b_norm <= ADCS_EPS_NORM) {
        return ADCS_E_DEGENERATE;
    }

    // 7. Compute raw inverse-square gain: g_raw = base_gain * (reference_field / b)^2
    double ratio = reference_field / b_norm;
    double g_raw = base_gain * ratio * ratio;

    // 8. Clamp gain to configured bounds [min_gain, max_gain]
    double gain_val;
    if (g_raw < min_gain) {
        gain_val = min_gain;
    } else if (g_raw > max_gain) {
        gain_val = max_gain;
    } else {
        gain_val = g_raw;
    }

    // 9. Compute unit field direction: field_direction = B / b
    field_direction->x = field->x / b_norm;
    field_direction->y = field->y / b_norm;
    field_direction->z = field->z / b_norm;

    // 10. Compute scheduled axis gain: scheduled_axis_gain = gain * field_direction
    *scheduled_axis_gain = adcs_vec3_scale(field_direction, gain_val);

    // 11. Assign final gain value
    *gain = gain_val;

    return ADCS_OK;
}

