candidates.raw:
    if ((field == NULL) || (gain == NULL) || (field_direction == NULL) || (scheduled_axis_gain == NULL)) {
        return ADCS_E_NULL;
    }

    if ((!adcs_is_finite_vec3(field)) || (!isfinite(base_gain)) || (base_gain < 0.0) ||
        (!isfinite(reference_field)) || (reference_field <= 0.0) ||
        (!isfinite(min_gain)) || (min_gain < 0.0) ||
        (!isfinite(max_gain)) || (max_gain < min_gain)) {
        return ADCS_E_RANGE;
    }

    double b = adcs_vec3_norm(field);
    if (b <= ADCS_EPS_NORM) {
        *gain = 0.0;
        *field_direction = (adcs_vec3_t){0.0, 0.0, 0.0};
        *scheduled_axis_gain = (adcs_vec3_t){0.0, 0.0, 0.0};
        return ADCS_E_DEGENERATE;
    }

    double g_raw = base_gain * (reference_field / b) * (reference_field / b);
    double clamped_gain = ADCS_CLAMP(g_raw, min_gain, max_gain);

    adcs_vec3_t dir = adcs_vec3_scale(field, 1.0 / b);

    *gain = clamped_gain;
    *field_direction = dir;
    *scheduled_axis_gain = adcs_vec3_scale(&dir, clamped_gain);

    return ADCS_OK;
}

